-- abyhub: Empyrean tab (armour, seal / +2 NMs, CatsEyeXI weapon trials).
-- abyhub.lua calls M.render(), M.tick(), M.command(args), M.load().
local chat = require('chat')
local imgui = require('imgui')
local bit = require('bit')

-- Generated by tools/build.py from retail data (client item text, retail drop rates).
local data = require('empydata')
-- Empyrean weapons: CatsEyeXI Magian trial chains (tools/build_weapons.py).
local wdata = require('empyweapons')

local T = require('abytheme')
local HUD, ui, CORNERS_ALL = T.HUD, T.ui, T.CORNERS_ALL
local rgba, col, pulse, line_h, text_w, DL = T.rgba, T.col, T.pulse, T.line_h, T.text_w, T.DL
local text, rtext, fit, dot, diamond = T.text, T.rtext, T.fit, T.dot, T.diamond
local frame, pill_w, pill, bar, card_bg, card_title, rule = T.frame, T.pill_w, T.pill, T.bar, T.card_bg, T.card_title, T.rule
local hit, advance, avail_w = T.hit, T.advance, T.avail_w
local seg_tabs, seg_width, toggle_chip, panel, band = T.seg_tabs, T.seg_width, T.toggle_chip, T.panel, T.band

local M = {}

--------------------------------------------------------------------------------
-- NM helpers
--------------------------------------------------------------------------------

-- "Zone|NM" -> zone, name
local function split_key(key)
    local zone, name = key:match('^(.-)|(.+)$')
    return zone, name
end

-- "Zone|NM" -> { [itemId] = drop % }   (built once)
local nm_drops_cache = nil
local function nm_drops()
    if nm_drops_cache == nil then
        nm_drops_cache = {}
        for iid, rows in pairs(data.drops) do
            for _, r in ipairs(rows) do
                nm_drops_cache[r.nm] = nm_drops_cache[r.nm] or {}
                nm_drops_cache[r.nm][iid] = r.pct
            end
        end
    end
    return nm_drops_cache
end

--------------------------------------------------------------------------------
-- State + settings
--------------------------------------------------------------------------------

local JOBS = { 'WAR', 'MNK', 'WHM', 'BLM', 'RDM', 'THF', 'PLD', 'DRK', 'BST', 'BRD',
               'RNG', 'SAM', 'NIN', 'DRG', 'SMN', 'BLU', 'COR', 'PUP', 'DNC', 'SCH' }
local SLOTS = { 'Head', 'Body', 'Hands', 'Legs', 'Feet' }

local state = {
    tab       = 1,          -- 1 armor, 2 nms, 3 weapons
    job       = nil,        -- picked job index; nil = follow main job
    compact   = false,
    slot      = 0,          -- nms tab: 0 all, 1..5
    tier      = 0,          -- nms tab: 0 both, 1 seals, 2 +2 items
    wtab      = 2,          -- weapons tab: 2 stages, 3 completed
    wsel      = nil,        -- stages view: picked weapon (index); nil = auto
}

local SAVED = { 'tab', 'job', 'compact', 'slot', 'tier', 'wtab', 'wsel' }

local function settings_file()
    return ('%s/abyhub_empyrean.lua'):format(addon.path)
end

local function save_settings()
    pcall(function()
        local f = io.open(settings_file(), 'w')
        if not f then return end
        local parts = {}
        for _, k in ipairs(SAVED) do
            local v = state[k]
            if v ~= nil then parts[#parts + 1] = ('%s = %s'):format(k, tostring(v)) end
        end
        f:write(('return { %s }\n'):format(table.concat(parts, ', ')))
        f:close()
    end)
end

local function load_settings()
    local ok, data = pcall(dofile, settings_file())
    if ok and type(data) == 'table' then
        for _, k in ipairs(SAVED) do
            if data[k] ~= nil then state[k] = data[k] end
        end
    end
end

local function msg(s)
    print(chat.header(addon.name):append(chat.message(s)))
end

--------------------------------------------------------------------------------
-- Game state: job, zone, bags
--------------------------------------------------------------------------------

local function main_job()
    local ok, job = pcall(function() return AshitaCore:GetMemoryManager():GetPlayer():GetMainJob() end)
    job = ok and tonumber(job) or 0
    if job >= 1 and job <= #JOBS then return job end
    return nil
end

local function job_index()
    return state.job or main_job() or 1
end

local function job_def()
    return data.jobs[job_index()]
end

local function player_zone_name()
    local ok, zid = pcall(function() return AshitaCore:GetMemoryManager():GetParty():GetMemberZone(0) end)
    if not ok then return nil end
    for name, id in pairs(data.zoneIds) do
        if id == zid then return name end
    end
    return nil
end

local held = {}
local last_scan = 0

local EQUIP_SLOTS = { [0] = 'MAIN', [1] = 'SUB', [2] = 'RANGE' }

-- "container:index" -> equip slot name for main / sub / range
local function scan_equipped(inv)
    local t = {}
    for slot, name in pairs(EQUIP_SLOTS) do
        pcall(function()
            local e = inv:GetEquippedItem(slot)
            if e == nil or e.Index == nil or e.Index == 0 then return end
            local idx = bit.band(e.Index, 0x00FF)
            local cont = bit.rshift(bit.band(e.Index, 0xFF00), 8)
            t[cont .. ':' .. idx] = name
        end)
    end
    return t
end

local on_scan = nil     -- set by the weapons section (decodes trial weapons)

local function scan_bags()
    local inv = AshitaCore:GetMemoryManager():GetInventory()
    if inv == nil then return end
    local t = {}
    local eq = scan_equipped(inv)
    local found = {}
    for c = 0, 16 do
        local max = tonumber(inv:GetContainerCountMax(c)) or 0
        for i = 0, max - 1 do
            local it = inv:GetContainerItem(c, i)
            if it ~= nil and it.Id ~= 0 and it.Id ~= 65535 then
                t[it.Id] = (t[it.Id] or 0) + (it.Count or 1)
                found[#found + 1] = { it = it, slot = eq[c .. ':' .. i] }
            end
        end
    end
    held = t
    if on_scan then on_scan(found) end
    last_scan = os.time()
end

local function have(id) return held[id] or 0 end

-- Highest tier owned for a piece: 2, 1, 0 (base) or -1 (none).
local function owned_tier(p)
    if have(p.p2.id) > 0 then return 2 end
    if have(p.p1.id) > 0 then return 1 end
    if have(p.base.id) > 0 then return 0 end
    return -1
end

--------------------------------------------------------------------------------
-- Weapons: trial detection
--
-- Each Magian trial weapon is a fixed item id plus one augment (Attack /
-- Rng.Atk. / DMG). An item on an active trial also carries the trial number
-- (and a "complete" bit) in its extdata, same layout the server writes:
--   byte 2  flags (0x40 = has trial)
--   3..10   up to 4 augments, uint16 each: id = low 11 bits, value = high 5 bits
--   11..12  trial number (15 bits) + complete bit
--------------------------------------------------------------------------------

local watched = {}      -- item id -> true for every trial / Empyrean item
for _, w in ipairs(wdata.weapons) do
    for _, s in ipairs(w.steps) do watched[s.id] = true end
    for _, ids in pairs(w.stages) do for _, id in ipairs(ids) do watched[id] = true end end
end

local copies = {}       -- item id -> { { aug_id, aug_val, trial, done, slot }, ... }
local wstate = {}       -- weapon name -> detected state (see weapon_state)

-- byte reader for an item's extdata; Ashita gives a string, but be lenient.
local function extra_reader(it)
    local ok, ex = pcall(function() return it.Extra end)
    if not ok or ex == nil then return function() return 0 end end
    if type(ex) == 'string' then return function(i) return ex:byte(i) or 0 end end
    return function(i)
        local ok2, v = pcall(function() return ex[i - 1] end)
        return (ok2 and tonumber(v)) or 0
    end
end

local function decode_copy(it)
    local b = extra_reader(it)
    local c = { aug_id = 0, aug_val = 0 }
    local flags = b(2)
    if bit.band(flags, 0x40) ~= 0 then
        c.trial = b(11) + bit.band(b(12), 0x7F) * 256
        c.done = b(12) >= 0x80
    end
    -- standard augments only (not crafted shields / path augments / evoliths)
    if bit.band(flags, 0x08) == 0 and bit.band(flags, 0x20) == 0 and bit.band(flags, 0x80) == 0 then
        local v = b(3) + b(4) * 256
        c.aug_id, c.aug_val = bit.band(v, 0x7FF), bit.rshift(v, 11)
    end
    return c
end

local function step_matches(s, c)
    if c.trial and c.trial ~= 0 then return c.trial == s.trial end
    if s.aug == nil then return c.aug_id == 0 end
    return c.aug_id == s.aug[1] and c.aug_val == s.aug[2]
end

-- idx: 0 not started, 1..#steps = working on that trial, #steps + 1 = Empyrean.
local function weapon_state(w)
    local st = { idx = 0 }
    local n = #w.steps
    for _, sl in ipairs(wdata.stage_labels) do
        for _, id in ipairs(w.stages[sl[1]] or {}) do
            for _, c in ipairs(copies[id] or {}) do
                st.idx, st.stage, st.slot, st.done = n + 1, sl[2], c.slot or st.slot, false
            end
        end
    end
    if st.idx > n then return st end
    for i, s in ipairs(w.steps) do
        for _, c in ipairs(copies[s.id] or {}) do
            if i >= st.idx and step_matches(s, c) then
                st.idx, st.slot, st.done = i, c.slot, c.done or false
            end
        end
    end
    return st
end

local function refresh_weapons()
    local t = {}
    for _, w in ipairs(wdata.weapons) do t[w.name] = weapon_state(w) end
    wstate = t
end

local function wstate_of(w) return wstate[w.name] or { idx = 0 } end

local function weapon_for_job(w, jn)
    for _, j in ipairs(w.jobs) do if j == jn then return true end end
    return false
end

-- Weapons for the shown job; any you have going for another job come after.
local function job_weapons()
    local jn = JOBS[job_index()]
    local mine, other = {}, {}
    for _, w in ipairs(wdata.weapons) do
        if weapon_for_job(w, jn) then mine[#mine + 1] = w
        elseif wstate_of(w).idx > 0 then other[#other + 1] = w end
    end
    return mine, other
end

local function weapons_held()
    local n = 0
    for _, w in ipairs(wdata.weapons) do if wstate_of(w).idx > 0 then n = n + 1 end end
    return n
end

on_scan = function(found)
    local t = {}
    for _, f in ipairs(found) do
        if watched[f.it.Id] then
            local c = decode_copy(f.it)
            c.slot = f.slot
            t[f.it.Id] = t[f.it.Id] or {}
            table.insert(t[f.it.Id], c)
        end
    end
    copies = t
    refresh_weapons()
end

ui.layout = nil


-- Each tier gets its own colour everywhere it appears.
local TIER_COL = { [0] = HUD.subtext, [1] = HUD.accent2, [2] = HUD.gold }
local TIER_NAME = { [0] = 'BASE', [1] = '+1', [2] = '+2' }

local function measure_layout()
    local lh = line_h()
    if ui.layout and ui.layout.lh == lh then return ui.layout end
    local L = { lh = lh, gap = 14 }

    L.header = 0   -- the header belongs to abyhub now

    -- NMs table: longest NM name + fixed columns
    local name_w = 0
    for iid, rows in pairs(data.drops) do
        for _, r in ipairs(rows) do local _, n = split_key(r.nm); name_w = math.max(name_w, text_w(n or r.nm)) end
    end
    local zone_w = 0
    for _, z in ipairs(data.zones) do zone_w = math.max(zone_w, text_w(z)) end
    L.zone_w = zone_w
    L.drop_w = text_w('224.6%')
    L.kill_w = math.max(text_w('KILLS'), text_w('~100'))
    L.nm_fixed = L.gap + zone_w + L.gap + L.drop_w + L.gap + L.kill_w
    L.nms = 24 + 16 + name_w + L.nm_fixed
    -- NMs filter row
    local seg = text_w('ALL') + text_w('HEAD') + text_w('BODY') + text_w('HANDS') + text_w('LEGS') + text_w('FEET') + 6 * 22
    L.nms = math.max(L.nms, seg + 14 + text_w('BOTH') + text_w('+1 SEALS') + text_w('+2 ITEMS') + 3 * 22)

    -- Armor: widest stat label + three value columns, two cards side by side if room
    local stat_w, up_w = 0, 0
    for _, j in ipairs(data.jobs) do
        for _, p in ipairs(j.pieces) do
            for _, t in ipairs({ p.base, p.p1, p.p2 }) do
                for _, st in ipairs(t.stats) do stat_w = math.max(stat_w, text_w(st[1])) end
            end
            up_w = math.max(up_w, text_w(('%dx %s'):format(p.up1.qty, p.up1.item)),
                                  text_w(('%dx %s'):format(p.up2.qty, p.up2.item)))
        end
    end
    local vw = math.max(text_w('+100%'), text_w('BASE')) + 10
    local card = 24 + math.max(stat_w + 8 + vw * 3, text_w('-> +2') + 10 + up_w + 50 + text_w('00/00') + 8)
    L.armor_one = card
    L.armor_two = card * 2 + 10

    -- Weapons: stages table + completed rows
    L.w_no, L.w_hold, L.w_obj, L.w_stat, L.w_wname, L.w_skill = text_w('TRIAL'), text_w('WEAPON'), 0, text_w('HAND IN'), 0, 0
    for _, w in ipairs(wdata.weapons) do
        L.w_wname = math.max(L.w_wname, text_w(w.name))
        L.w_skill = math.max(L.w_skill, text_w(w.skill))
        for _, s in ipairs(w.steps) do
            L.w_no = math.max(L.w_no, text_w(tostring(s.trial)))
            L.w_hold = math.max(L.w_hold, text_w(s.label))
            local o = s.obj
            L.w_obj = math.max(L.w_obj, text_w(o.kind == 'defeat' and ('Defeat %s x%d'):format(o.target, o.qty)
                or ('Trade %dx %s'):format(o.qty, o.item)))
        end
    end
    L.weapons = 18 + L.w_no + L.gap + L.w_hold + L.gap + L.w_obj + L.gap + L.w_stat + 8

    L.min = math.max(L.nms, L.armor_one, L.weapons, 52 * text_w('0'))
    L.want = math.max(L.min, L.header, L.armor_two)
    ui.layout = L
    return L
end

local function nm_name(key)
    local _, name = split_key(key)
    return name or key
end

local function nm_zone(key)
    local zone = split_key(key)
    return zone
end

local function nm_tooltip(key, extra)
    local lines = { nm_name(key) .. '  -  Abyssea - ' .. (nm_zone(key) or '?') }
    if extra then for _, l in ipairs(extra) do lines[#lines + 1] = l end end
    imgui.SetTooltip(table.concat(lines, '\n'))
end

--------------------------------------------------------------------------------
local function set_progress()
    local done, total = 0, 0
    for _, p in ipairs(job_def().pieces) do
        total = total + 2
        local t = owned_tier(p)
        if t >= 1 then done = done + 1 end
        if t >= 2 then done = done + 1 end
    end
    return done, total
end

local function render_job_picker()
    if not ui.picker then return end
    local mj = main_job()
    local items = { { 0, 'AUTO', mj and JOBS[mj] or nil, HUD.gold } }
    for i, j in ipairs(JOBS) do
        local d = 0
        for _, pc in ipairs(data.jobs[i].pieces) do d = d + math.max(0, owned_tier(pc)) end
        items[#items + 1] = { i, j, d > 0 and tostring(d) or nil, d >= 10 and HUD.owned or nil }
    end
    band('jobpick', function(x, y, w)
        -- flow the chips into as many rows as the width needs
        local rows, row, rw = {}, {}, 0
        for _, it in ipairs(items) do
            local iw = seg_width({ it }, true) + 6
            if rw + iw > w and #row > 0 then rows[#rows + 1] = row; row, rw = {}, 0 end
            row[#row + 1] = it
            rw = rw + iw
        end
        rows[#rows + 1] = row
        local active = state.job or 0
        local picked, th = nil, line_h() + 10
        for ri, r in ipairs(rows) do
            local p = seg_tabs('empy_job' .. ri, r, active, x, y + (ri - 1) * (th + 4), HUD.gold, true)
            if p ~= nil then picked = p end
        end
        if picked ~= nil then
            state.job = (picked ~= 0) and picked or nil
            ui.picker = false
            save_settings()
        end
        return #rows * (th + 4) - 4
    end)
end

--------------------------------------------------------------------------------
-- Armor tab
--------------------------------------------------------------------------------

local function stat_rows(p)
    local rows, seen, maps = {}, {}, {}
    for i, t in ipairs({ p.base, p.p1, p.p2 }) do
        maps[i] = {}
        for _, s in ipairs(t.stats) do
            maps[i][s[1]] = s[2]
            if not seen[s[1]] then seen[s[1]] = true; rows[#rows + 1] = s[1] end
        end
    end
    return rows, maps
end

local function upgrade_line(x, y, w, tier, up, reached)
    local lh = line_h()
    local h = have(up.id)
    local tc = TIER_COL[tier]
    local done = reached or h >= up.qty
    local lbl = '-> ' .. TIER_NAME[tier]
    text(x, y, tc, lbl)
    local nx = x + text_w('-> +2') + 10
    local count = reached and 'DONE' or ('%d/%d'):format(math.min(h, up.qty), up.qty)
    local cw = text_w('00/00') + 8
    local name = fit(('%dx %s'):format(up.qty, up.item), w - (nx - x) - cw - 70)
    text(nx, y, done and HUD.subtext or HUD.text, name)
    rtext(x + w, y, done and HUD.owned or HUD.muted, count)
    local bx = nx + text_w(name) + 10
    local bw = x + w - cw - bx - 6
    if bw > 20 then bar(bx, y + lh * 0.5 - 1.5, bw, 3, reached and 1 or (h / up.qty), done and HUD.owned or tc) end
end

-- One slot card; returns content height.
local function draw_piece(p, x, y, w, h)
    local dl = DL()
    local lh = line_h()
    local ot = owned_tier(p)
    card_bg(x, y, w, h, ot >= 0 and TIER_COL[ot] or nil, ot == 2 and 0.9 or 0.6)
    dl:PushClipRect({ x, y }, { x + w, y + h }, true)

    local px, py, pw = x + 12, y + 9, w - 24
    local name = ('%s  Lv.%d'):format(p.base.name, p.base.lv)
    local tag = ot >= 0 and TIER_NAME[ot] or 'NOT OWNED'
    local tag_c = ot >= 0 and TIER_COL[ot] or HUD.faint
    card_title(px, py, pw, ot >= 0 and TIER_COL[ot] or HUD.muted, p.slot:upper(),
        fit(name, pw - text_w(p.slot:upper()) - pill_w(tag) - 30))
    pill(px + pw - pill_w(tag), py, tag, tag_c, ot == 2 and (0.12 + pulse(2) * 0.08) or 0.12)
    py = py + lh + 8

    if not state.compact then
        local vw = math.max(text_w('+100%'), text_w('BASE')) + 10
        local sx = px + pw - vw * 3
        -- column heads
        for i = 0, 2 do
            local c = (ot == i) and HUD.owned or HUD.faint
            rtext(sx + vw * (i + 1), py, c, TIER_NAME[i])
        end
        py = py + lh + 3
        local rows, maps = stat_rows(p)
        for ri, k in ipairs(rows) do
            if ri % 2 == 1 then
                dl:AddRectFilled({ px - 4, py - 1 }, { px + pw + 4, py + lh + 1 }, col(HUD.text, 0.025), 4)
            end
            local shown = fit(k, sx - px - 6)
            text(px, py, HUD.subtext, shown)
            if shown ~= k then
                local _, hv = hit(('##st_%s_%d'):format(p.slot, ri), px, py, sx - px - 6, lh)
                if hv then imgui.SetTooltip(k) end
            end
            local prev = nil
            for i = 1, 3 do
                local v = maps[i][k]
                local c
                if v == nil then v, c = '-', HUD.faint
                elseif prev ~= nil and v ~= prev then c = TIER_COL[i - 1]
                elseif prev == nil and i > 1 then c = TIER_COL[i - 1]
                else c = HUD.text end
                rtext(sx + vw * i, py, c, v)
                if maps[i][k] ~= nil then prev = maps[i][k] end
            end
            py = py + lh + 2
        end
        py = py + 6
    end

    upgrade_line(px, py, pw, 1, p.up1, ot >= 1)
    py = py + lh + 4
    upgrade_line(px, py, pw, 2, p.up2, ot >= 2)
    py = py + lh + 4

    dl:PopClipRect()
    return (py - y) + 10
end

local function render_armor()
    local lh = line_h()
    local x, y = imgui.GetCursorScreenPos()
    local w = avail_w()
    local jd = job_def()

    -- Summary strip
    local d, t = set_progress()
    local sh = lh + 16
    card_bg(x, y, w, sh, HUD.gold, 0.6)
    local tx = x + 10
    text(tx, y + 8, HUD.muted, jd.set:upper() .. ' SET')
    tx = tx + text_w(jd.set:upper() .. ' SET') + 10
    local cnt = ('%d / %d upgrades'):format(d, t)
    text(tx, y + 8, HUD.text, cnt)
    tx = tx + text_w(cnt) + 12
    local cx = x + w - 10
    local chip_x = cx - (text_w('Compact') + 34)
    local bw = chip_x - tx - 14
    bar(tx, y + sh * 0.5 - 2, bw, 4, d / math.max(1, t), d == t and HUD.owned or HUD.gold)
    local cc = toggle_chip('##empy_compact2', 'Compact', state.compact, chip_x, y + (sh - (lh + 10)) * 0.5, HUD.accent)
    if cc then state.compact = not state.compact; save_settings() end
    advance(w, sh)

    -- set bonus (from the +2 pieces' item text)
    if jd.bonus and jd.bonus ~= '' then
        x, y = imgui.GetCursorScreenPos()
        text(x + 4, y, HUD.muted, 'Set bonus (+2 pieces):')
        text(x + 4 + text_w('Set bonus (+2 pieces):') + 8, y, HUD.gold, jd.bonus)
        advance(w, lh)
    end

    -- Slot cards: two columns when wide.
    local gap = 10
    -- two columns whenever there's reasonable room; long stat names shorten (hover shows them)
    local cols = (w >= math.min(ui.layout.armor_two, 760)) and 2 or 1
    local cw = (w - gap * (cols - 1)) / cols
    local pieces = jd.pieces
    local i = 1
    while i <= #pieces do
        x, y = imgui.GetCursorScreenPos()
        local key = ('armor_%d_%d'):format(cols, i)
        local h = ui.h[key] or 160
        local max_h = 0
        for c = 0, cols - 1 do
            local p = pieces[i + c]
            if p then
                max_h = math.max(max_h, draw_piece(p, x + c * (cw + gap), y, cw, h))
            end
        end
        ui.h[key] = max_h
        advance(w, h)
        imgui.Dummy({ 0, 2 })
        i = i + cols
    end
end

--------------------------------------------------------------------------------
-- NMs tab
--------------------------------------------------------------------------------

local function also_drops(key, except)
    local d = nm_drops()[key] or {}
    local names = {}
    for iid, _ in pairs(d) do
        if iid ~= except and data.matNames[iid] then names[#names + 1] = data.matNames[iid] end
    end
    table.sort(names)
    return names
end

local function render_material(slot, tier, up, here, reached)
    local id = ('mat_%d'):format(up.id)
    local tc = TIER_COL[tier]
    panel(id, tc, function(x, y, w)
        local dl = DL()
        local lh = line_h()
        local h = have(up.id)
        local need = reached and 0 or math.max(0, up.qty - h)
        local right = reached and 'PIECE DONE' or ('%d / %d'):format(math.min(h, up.qty), up.qty)
        local right_c = (need == 0) and HUD.owned or HUD.muted
        card_title(x, y, w, tc, up.item, ('%s %s'):format(slot:upper(), TIER_NAME[tier]), right, right_c)
        local py = y + lh + 6
        bar(x, py, w, 3, reached and 1 or (h / up.qty), need == 0 and HUD.owned or tc)
        py = py + 3 + 8

        -- column layout (widths measured once in measure_layout)
        local L = ui.layout
        local c_name = x + 16
        local name_w = math.max(40, w - 16 - L.nm_fixed)
        local c_zone = c_name + name_w + L.gap
        local c_drop = c_zone + L.zone_w + L.gap + L.drop_w      -- right edge
        local c_kill = x + w                                     -- right edge

        text(c_name, py, HUD.faint, 'NM')
        text(c_zone, py, HUD.faint, 'ZONE')
        rtext(c_drop, py, HUD.faint, 'DROP')
        rtext(c_kill, py, HUD.faint, 'KILLS')
        py = py + lh + 3

        for ri, r in ipairs(data.drops[up.id] or {}) do
            local zone = nm_zone(r.nm)
            local is_here = zone == here
            local _, hov = hit(('##%s_%d'):format(id, ri), x - 4, py - 1, w + 8, lh + 2)
            if hov then
                dl:AddRectFilled({ x - 4, py - 1 }, { x + w + 4, py + lh + 1 }, col(HUD.text, 0.06), 4)
                local also = also_drops(r.nm, up.id)
                local tip = { ('%.1f%% per kill%s'):format(r.pct, r.pct > 100 and ' (more than one per kill on average)' or '') }
                if ri == 1 then tip[#tip + 1] = 'Best source for this item' end
                if #also > 0 then tip[#tip + 1] = 'Also drops: ' .. table.concat(also, ', ') end
                nm_tooltip(r.nm, tip)
            elseif ri % 2 == 1 then
                dl:AddRectFilled({ x - 4, py - 1 }, { x + w + 4, py + lh + 1 }, col(HUD.text, 0.025), 4)
            end
            dot(x + 5, py + lh * 0.5, 3.5, ri == 1 and HUD.owned or (is_here and HUD.gold or HUD.faint),
                is_here and (0.5 + pulse(3) * 0.5) or 0)
            text(c_name, py, is_here and HUD.gold or HUD.text, fit(nm_name(r.nm), name_w))
            text(c_zone, py, is_here and HUD.gold or HUD.subtext, zone)
            rtext(c_drop, py, HUD.text, ('%.1f%%'):format(r.pct))
            local k = (need == 0) and '-' or ('~%d'):format(math.ceil(need / math.max(r.pct / 100, 0.01)))
            rtext(c_kill, py, need == 0 and HUD.faint or HUD.subtext, k)
            py = py + lh + 3
        end
        return py - y - 3
    end, 0.7)
end

local function render_nms()
    local lh = line_h()
    local here = player_zone_name()

    band('nmfilt', function(x, y, w)
        local slots = { { 0, 'ALL' } }
        for i, sl in ipairs(SLOTS) do slots[#slots + 1] = { i, sl:upper() } end
        local sp, sw, th = seg_tabs('empy_slot', slots, state.slot, x, y, HUD.gold, true)
        if sp then state.slot = sp; save_settings() end
        local tiers = { { 0, 'BOTH' }, { 1, '+1 SEALS' }, { 2, '+2 ITEMS' } }
        local tx = x + sw + 14
        DL():AddLine({ tx - 7, y + 5 }, { tx - 7, y + th - 5 }, col(HUD.edge, 0.5), 1)
        local tp = seg_tabs('empy_tier', tiers, state.tier, tx, y, HUD.accent, true)
        if tp then state.tier = tp; save_settings() end
        if here then
            local s = 'In Abyssea - ' .. here
            pill(x + w - pill_w(s) - 4, y + (th - lh) * 0.5, s, HUD.gold, 0.10)
        end
        return th
    end)

    local x, y = imgui.GetCursorScreenPos()
    diamond(x + 8, y + lh * 0.5, 4, HUD.owned, true)
    text(x + 18, y, HUD.muted, 'best source   |   retail drop rates, over 100% = more than one per kill')
    advance(avail_w(), lh + 2)
    imgui.Dummy({ 0, 2 })

    for i, p in ipairs(job_def().pieces) do
        if state.slot == 0 or state.slot == i then
            local ot = owned_tier(p)
            if state.tier ~= 2 then render_material(p.slot, 1, p.up1, here, ot >= 1) end
            if state.tier ~= 1 then render_material(p.slot, 2, p.up2, here, ot >= 2) end
        end
    end
end

--------------------------------------------------------------------------------
-- Weapons tab: STAGES (one weapon's trial path) / COMPLETED
--------------------------------------------------------------------------------

local function obj_text(o)
    if o.kind == 'defeat' then return ('Defeat %s x%d'):format(o.target, o.qty) end
    return ('Trade %dx %s'):format(o.qty, o.item)
end

local function obj_where(o)
    if o.kind == 'defeat' then return o.zone and ('Abyssea - ' .. o.zone) or 'Field / dungeon' end
    return ('%s  -  Abyssea - %s'):format(o.nm, o.zone)
end

-- have, need for trade trials; nil for defeat trials (kills are tracked server-side)
local function obj_count(o)
    if o.kind ~= 'trade' then return nil end
    return math.min(have(o.id), o.qty), o.qty
end

-- defeat objectives read yellow, trade objectives white (as in the trial list)
local function obj_col(o) return o.kind == 'defeat' and HUD.yellow or HUD.text end

local function weapon_index(w)
    for i, x in ipairs(wdata.weapons) do if x == w then return i end end
    return 1
end

local function selected_weapon()
    local w = wdata.weapons[state.wsel or 0]
    if w then return w end
    local mine = job_weapons()
    for _, x in ipairs(mine) do if wstate_of(x).idx > 0 then return x end end
    return mine[1] or wdata.weapons[1]
end

local function open_stages(w)
    state.wsel = weapon_index(w)
    state.wtab = 2
    save_settings()
end

local function status_of(w)
    local st = wstate_of(w)
    local n = #w.steps
    if st.idx > n then return ('EMPYREAN %s'):format(st.stage or ''), HUD.gold end
    if st.done then return 'HAND IN', HUD.owned end
    if st.idx > 0 then return ('TRIAL %d/%d'):format(st.idx, n), HUD.accent2 end
    return 'NOT STARTED', HUD.accent
end

local function counts()
    local prog, done = 0, 0
    for _, w in ipairs(wdata.weapons) do
        local st = wstate_of(w)
        if st.idx > #w.steps then done = done + 1 elseif st.idx > 0 then prog = prog + 1 end
    end
    return prog, done
end

-- Weapon heading: diamond, name, skill  >  jobs | equip slot, status tag
local function weapon_heading(x, y, pw, w)
    local lh = line_h()
    local st = wstate_of(w)
    local tag, tc = status_of(w)
    local scale = 1.22
    diamond(x + 7, y + lh * 0.55, 7, HUD.lavender, false, 0.6)
    text(x + 22, y - 1, HUD.lavender, w.name, scale)
    local sx = x + 22 + text_w(w.name) * scale + 14
    text(sx, y, HUD.muted, w.skill)
    sx = sx + text_w(w.skill) + 12
    -- small arrow
    local ay = y + lh * 0.5
    DL():AddLine({ sx, ay }, { sx + 12, ay }, col(HUD.muted), 1.3)
    DL():AddLine({ sx + 8, ay - 3.5 }, { sx + 12, ay }, col(HUD.muted), 1.3)
    DL():AddLine({ sx + 8, ay + 3.5 }, { sx + 12, ay }, col(HUD.muted), 1.3)
    text(sx + 20, y, HUD.subtext, table.concat(w.jobs, ' '))
    local px = x + pw - pill_w(tag)
    pill(px, y, tag, tc, 0.10)
    if st.slot then pill(px - 8 - pill_w(st.slot), y, st.slot, HUD.owned, 0.10) end
    return lh + 6
end

-- Framed footer note inside a panel.
local function footer(x, y, pw, s, c)
    local lh = line_h()
    local h = lh + 14
    frame(x - 4, y, pw + 8, h, { k = 5, fill = HUD.header_bg, glow = 0.4, alpha = 0.6 })
    diamond(x + 10, y + h * 0.5, 6, HUD.edge_hi, false, 0.5)
    text(x + 26, y + 7, c or HUD.subtext, fit(s, pw - 34))
    return h
end

-- STAGES -------------------------------------------------------------------

local function weapon_picker()
    local sel = selected_weapon()
    local jn = JOBS[job_index()]
    local order = {}
    for _, wp in ipairs(wdata.weapons) do if weapon_for_job(wp, jn) then order[#order + 1] = wp end end
    for _, wp in ipairs(wdata.weapons) do if not weapon_for_job(wp, jn) then order[#order + 1] = wp end end
    local items = {}
    for _, wp in ipairs(order) do
        local st = wstate_of(wp)
        local light = nil
        if st.idx > #wp.steps then light = HUD.owned          -- green: Empyrean obtained
        elseif st.idx > 0 then light = HUD.yellow end         -- yellow: being worked on
        items[#items + 1] = { weapon_index(wp), wp.name, nil, nil, light }
    end
    band('wpick', function(x, y, w)
        -- as few rows as fit, with the weapons spread evenly over them
        local nrows = math.max(1, math.ceil(seg_width(items, true) / w))
        local rows
        while true do
            rows = {}
            local per = math.ceil(#items / nrows)
            for i, it in ipairs(items) do
                local r = math.floor((i - 1) / per) + 1
                rows[r] = rows[r] or {}
                table.insert(rows[r], it)
            end
            local ok = true
            for _, r in ipairs(rows) do if seg_width(r, true) > w then ok = false end end
            if ok or nrows >= #items then break end
            nrows = nrows + 1
        end
        local th = line_h() + 10
        for ri, r in ipairs(rows) do
            local p = seg_tabs('wpick' .. ri, r, weapon_index(sel), x, y + (ri - 1) * (th + 4), HUD.gold, true,
                { width = w, dividers = true })
            if p then state.wsel = p; save_settings() end
        end
        return #rows * (th + 4) - 4
    end)
end

local function render_stages(here_zone)
    weapon_picker()
    local w = selected_weapon()
    local st = wstate_of(w)
    local n = #w.steps
    local got = st.idx > n
    panel('stages_' .. w.name, HUD.edge_hi, function(x, y, pw)
        local dl = DL()
        local lh = line_h()
        local py = y + weapon_heading(x, y, pw, w) + 6
        rule(x - 6, py, pw + 12, HUD.edge_hi, 0.7)
        py = py + 8

        -- table
        local L = ui.layout
        local rh = lh + 10
        local tx, tw = x, pw
        local c_ic = tx + 14
        local c_no = tx + 30
        local d1 = c_no + L.w_no + 18
        local c_hold = d1 + 14
        local d2 = c_hold + L.w_hold + 18
        local c_obj = d2 + 14
        local c_end = tx + tw - 12
        local d3 = c_end - L.w_stat - 16
        local obj_w = d3 - c_obj - 10
        local rows = n + 1
        local th = rh + rows * rh + 4
        frame(tx, py, tw, th, { k = 5, fill = HUD.inset, glow = 0.3, alpha = 0.55 })
        -- header
        local hy = py + (rh - lh) * 0.5
        text(c_no - 6, hy, HUD.accent2, 'TRIAL')
        text(c_hold, hy, HUD.accent2, 'WEAPON')
        text(c_obj, hy, HUD.accent2, 'OBJECTIVE')
        rtext(c_end, hy, HUD.accent2, 'STATUS')
        for _, dx in ipairs({ d1, d2, d3 }) do
            dl:AddLine({ dx, py + 6 }, { dx, py + rh - 6 }, col(HUD.edge_hi, 0.6), 1.2)
            dl:AddLine({ dx, py + rh }, { dx, py + th - 4 }, col(HUD.edge, 0.22), 1)
        end
        dl:AddLine({ tx + 4, py + rh }, { tx + tw - 4, py + rh }, col(HUD.edge_hi, 0.55), 1)
        local ry = py + rh

        local function row_bg(i, cur, hv)
            if cur then
                frame(tx + 3, ry + 1, tw - 6, rh - 2, { k = 3, fill = HUD.sel_fill, edge = HUD.edge_hi, glow = 0.7, alpha = 0.9 })
            elseif hv then
                dl:AddRectFilled({ tx + 3, ry + 1 }, { tx + tw - 3, ry + rh - 1 }, col(HUD.sel_fill, 0.45))
            end
            if i < rows then dl:AddLine({ tx + 6, ry + rh }, { tx + tw - 6, ry + rh }, col(HUD.row_line), 1) end
        end

        for i, s in ipairs(w.steps) do
            local passed = i < st.idx or got
            local cur = i == st.idx and not got
            local o = s.obj
            local _, hv = hit(('##stg_%s_%d'):format(w.name, i), tx, ry, tw, rh)
            row_bg(i, cur, hv)
            local ty = ry + (rh - lh) * 0.5
            if passed then diamond(c_ic, ry + rh * 0.5, 5, HUD.gold, true)
            elseif cur then diamond(c_ic, ry + rh * 0.5, 5.5, HUD.accent2, true, 0.5 + pulse(3) * 0.5)
            else diamond(c_ic, ry + rh * 0.5, 5, HUD.lavender, false) end

            local dim = passed and 0.55 or 1
            text(c_no, ty, rgba(HUD.subtext, dim), tostring(s.trial))
            text(c_hold, ty, rgba(cur and HUD.text or HUD.accent2, dim), fit(s.label, d2 - c_hold - 8))
            local ot = fit(obj_text(o), obj_w)
            text(c_obj, ty, rgba(obj_col(o), dim), ot)
            if o.zone and o.zone == here_zone and not passed then
                local hx = c_obj + text_w(ot) + 10
                if hx + text_w('HERE') + 14 < d3 then pill(hx, ty, 'HERE', HUD.gold, 0.12) end
            end

            local stat, sc
            if passed then stat, sc = 'DONE', HUD.gold
            elseif cur and st.done then stat, sc = 'HAND IN', HUD.owned
            else
                local h, need = obj_count(o)
                if h then stat, sc = ('%d/%d'):format(h, need), (h >= need) and HUD.owned or HUD.text
                else stat, sc = '-', HUD.subtext end
            end
            rtext(c_end, ty, sc, stat)

            if hv then
                local tip = { ('Trial %d:  %s  >  %s'):format(s.trial, s.label, s.to), obj_text(o), obj_where(o) }
                if o.kind == 'defeat' then tip[#tip + 1] = 'The weapon must be equipped when it dies.'
                else tip[#tip + 1] = 'Trade the items + weapon to the Delivery Crate by the Magian Moogle.' end
                if o.changed then tip[#tip + 1] = 'Changed on CatsEyeXI.' end
                imgui.SetTooltip(table.concat(tip, '\n'))
            end
            ry = ry + rh
        end

        -- final row: the Empyrean itself
        row_bg(rows, false, false)
        local ty = ry + (rh - lh) * 0.5
        if got then diamond(c_ic, ry + rh * 0.5, 6, HUD.gold, true, 0.6 + pulse(2) * 0.4)
        else diamond(c_ic, ry + rh * 0.5, 5, HUD.lavender, false) end
        text(c_no, ty, HUD.faint, '-')
        text(c_hold, ty, got and HUD.gold or HUD.accent2, w.name)
        text(c_obj, ty, HUD.subtext, fit('Stage 2 and 3: not on ' .. (wdata.source or 'the server') .. ' yet', obj_w))
        rtext(c_end, ty, got and HUD.gold or HUD.subtext, got and 'OWNED' or '-')
        py = py + th + 10

        -- footer
        local note, nc
        if got then note, nc = w.name .. ' obtained.', HUD.gold
        elseif st.idx == 0 then note = ('Start: take a %s from the %s.'):format(w.steps[1].label, wdata.start)
        elseif st.done then note, nc = 'Trial complete: trade the weapon to the Magian Moogle for the next one.', HUD.owned
        else
            local o = w.steps[st.idx].obj
            note = o.kind == 'defeat' and ('Kill %s with the weapon equipped  -  %s'):format(o.target, obj_where(o))
                or ('Bring %dx %s (%s) and the weapon to the Delivery Crate by the Magian Moogle.'):format(o.qty, o.item, o.nm)
        end
        py = py + footer(x, py, pw, note, nc)
        return py - y
    end, 1.0)
end

-- COMPLETED ----------------------------------------------------------------

local function render_completed()
    local lh = line_h()
    local done, todo = {}, {}
    for _, w in ipairs(wdata.weapons) do
        if wstate_of(w).idx > #w.steps then done[#done + 1] = w else todo[#todo + 1] = w end
    end
    panel('completed', HUD.edge_hi, function(x, y, pw)
        local dl = DL()
        local total = #wdata.weapons
        diamond(x + 7, y + lh * 0.55, 7, HUD.lavender, false, 0.6)
        text(x + 22, y - 1, HUD.lavender, 'Empyrean Weapons', 1.22)
        rtext(x + pw, y, #done == total and HUD.owned or HUD.gold, ('%d / %d'):format(#done, total))
        local py = y + lh + 8
        bar(x, py, pw, 3, #done / math.max(1, total), HUD.gold)
        py = py + 3 + 10

        local L = ui.layout
        local rh = lh + 10
        local rows = math.max(1, #done)
        local th = rows * rh + 4
        frame(x, py, pw, th, { k = 5, fill = HUD.inset, glow = 0.3, alpha = 0.55 })
        if #done == 0 then
            text(x + 14, py + (rh - lh) * 0.5 + 2, HUD.muted, 'None yet - finish all 10 trials of a weapon to see it here.')
        end
        local ry = py + 2
        for i, w in ipairs(done) do
            local st = wstate_of(w)
            local clicked, hv = hit('##done_' .. w.name, x, ry, pw, rh)
            if clicked then open_stages(w) end
            if hv then dl:AddRectFilled({ x + 3, ry + 1 }, { x + pw - 3, ry + rh - 1 }, col(HUD.sel_fill, 0.45)) end
            if i < #done then dl:AddLine({ x + 6, ry + rh }, { x + pw - 6, ry + rh }, col(HUD.row_line), 1) end
            local ty = ry + (rh - lh) * 0.5
            diamond(x + 14, ry + rh * 0.5, 5, HUD.gold, true)
            text(x + 30, ty, HUD.text, w.name)
            local c2 = x + 30 + L.w_wname + 20
            text(c2, ty, HUD.muted, w.skill)
            text(c2 + L.w_skill + 20, ty, HUD.accent2, table.concat(w.jobs, ' '))
            local tag = st.stage or 'Lv80'
            local px = x + pw - 10 - pill_w(tag)
            pill(px, ty, tag, HUD.gold, 0.10)
            if st.slot then pill(px - 8 - pill_w(st.slot), ty, st.slot, HUD.owned, 0.10) end
            ry = ry + rh
        end
        py = py + th + 10
        if #todo > 0 then
            -- wrapped list of the weapons still to do
            local lines, cur = {}, 'Still to do: '
            for i, w in ipairs(todo) do
                local piece = w.name .. (i < #todo and ', ' or '')
                if text_w(cur .. piece) > pw - 40 and cur ~= '' then lines[#lines + 1] = cur; cur = '' end
                cur = cur .. piece
            end
            lines[#lines + 1] = cur
            local fh = #lines * (lh + 3) + 11
            frame(x - 4, py, pw + 8, fh, { k = 5, fill = HUD.header_bg, glow = 0.4, alpha = 0.6 })
            diamond(x + 10, py + 7 + lh * 0.5, 6, HUD.edge_hi, false, 0.5)
            for li, l in ipairs(lines) do text(x + 26, py + 6 + (li - 1) * (lh + 3), HUD.muted, l) end
            py = py + fh
        end
        return py - y
    end, 1.0)
end

-- tab ----------------------------------------------------------------------

local function render_weapons()
    local here = player_zone_name()
    if state.wtab == 3 then render_completed()
    else render_stages(here) end
end

--------------------------------------------------------------------------------
-- Section entry points (called from abyhub.lua)
--------------------------------------------------------------------------------

-- Width the Empyrean views need (so abyhub keeps one width on every tab).
function M.min_width()
    local L = measure_layout()
    return L.min, L.armor_two
end

-- Called every frame while the window is open on the Empyrean tab.
function M.tick()
    if os.time() - last_scan >= 5 then pcall(scan_bags) end
end

function M.render()
    measure_layout()
    local lh = line_h()
    local d, t = set_progress()
    local nw = weapons_held()
    local prog, done = counts()

    band('empy_bar', function(x, y, w)
        local tabs = {
            { 1, 'ARMOR', ('%d/%d'):format(d, t), d == t and HUD.owned or nil },
            { 2, 'NMS' },
            { 3, 'WEAPONS', nw > 0 and tostring(nw) or nil },
        }
        local p, tw, th = seg_tabs('empy_tab', tabs, state.tab, x, y, HUD.gold, true)
        if p and p ~= state.tab then state.tab = p; save_settings() end

        -- job pill on the right (click for the job picker)
        local jd = job_def()
        local follow = state.job == nil
        local jw = T.dot_pill_w(JOBS[job_index()], jd.set)
        local jx, jy = x + w - jw - 2, y + (th - (lh + 10)) * 0.5
        local jc = T.dot_pill('##empy_job', jx, jy, JOBS[job_index()], HUD.gold, jd.set, HUD.gold, follow)
        if jc then ui.picker = not ui.picker end

        local h = th
        if state.tab == 3 then
            local sub = {
                { 2, 'STAGES' },
                { 3, 'COMPLETED', ('%d/%d'):format(done, #wdata.weapons), HUD.gold },
            }
            local sw = seg_width(sub, true)
            local sx, sy = x + tw + 22, y
            if sx + sw > jx - 12 then sx, sy = x, y + th + 6; h = th * 2 + 6 end
            if sy == y then DL():AddLine({ sx - 11, y + 5 }, { sx - 11, y + th - 5 }, col(HUD.edge, 0.5), 1) end
            local sp = seg_tabs('wtab', sub, state.wtab, sx, sy, HUD.gold, true)
            if sp and sp ~= state.wtab then state.wtab = sp; save_settings() end
        end
        return h
    end)
    render_job_picker()

    if state.tab == 2 then render_nms()
    elseif state.tab == 3 then render_weapons()
    else render_armor() end
end

-- /aby armor | nms | weapons [stages|completed] | job <JOB|auto> | refresh | compact
-- args[1] is the sub-command. Returns true when the Empyrean tab should be shown.
function M.command(args)
    local cmd = (args[1] or ''):lower()
    local function open(t) if t then state.tab = t end; save_settings(); return true end

    if cmd == 'armor' or cmd == 'armour' then
        return open(1)
    elseif cmd == 'nms' then
        return open(2)
    elseif cmd == 'weapons' then
        local sub = (args[2] or ''):lower()
        if sub == 'stages' then state.wtab = 2
        elseif sub == 'completed' or sub == 'done' then state.wtab = 3 end
        return open(3)
    elseif cmd == 'job' then
        local want = (args[2] or ''):upper()
        if want == '' or want == 'AUTO' then
            state.job = nil
            msg('Following your main job.')
        else
            local found = nil
            for i, jn in ipairs(JOBS) do if jn == want then found = i end end
            if found then
                state.job = found
                msg(('Showing %s (%s).'):format(JOBS[found], data.jobs[found].set))
            else
                msg('Unknown job: ' .. want)
            end
        end
        return open(nil)
    elseif cmd == 'compact' then
        state.compact = not state.compact
        return open(nil)
    elseif cmd == 'refresh' then
        pcall(scan_bags)
        msg('Bags rescanned.')
        return false
    end
    return false
end

function M.load()
    load_settings()
    if state.wtab ~= 3 then state.wtab = 2 end
    pcall(scan_bags)
end

return M
